from pathlib import Path
import json,html
root=Path('art/sdp-card-set-01');record=json.loads((root/'results.json').read_text(encoding='utf-8'));current={x['id']:x for x in json.loads((root/'current-cards.json').read_text(encoding='utf-8'))};qa={x['id']:x for x in json.loads((root/'qa.json').read_text(encoding='utf-8'))};cards=[]
for item in record['items']:
 assert (root/'prepared'/f"{item['id']}.png").exists()
 cards.append({**{k:item[k] for k in ['id','name','kind','native_size']},**current[item['id']],'qa':qa[item['id']]})
assert len(cards)==10 and len({x['id'] for x in cards})==10
payload=json.dumps(cards).replace('<','\\u003c')
head='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SDP cards — all 10</title>
<link rel="stylesheet" href="/src/styles/tokens.css"><link rel="stylesheet" href="/src/styles/app.css"><link rel="stylesheet" href="/src/styles/components.css"><link rel="stylesheet" href="/src/components/ui/Button.css"><link rel="stylesheet" href="/src/components/ui/PixelFrame.css"><link rel="stylesheet" href="/src/components/sdp/sdp-components.css"><link rel="stylesheet" href="/src/dev/sdp-workspace/sdp-dashboard.css">
<style>
body{background:var(--color-vanilla)}.review{max-width:1540px;margin:auto;padding:24px 16px;color:var(--color-wine)}.review>header{border-bottom:2px solid var(--color-wine);padding-bottom:20px;margin-bottom:24px}.review>header h1{font-size:1.5rem;line-height:1.2;margin-bottom:12px}.review p{max-width:95ch;line-height:1.25}.review>header p{margin:8px 0}.review a{color:var(--color-wine);text-underline-offset:3px}.card-index{display:flex;flex-wrap:wrap;gap:8px 16px;margin-top:16px}.card-index a{display:inline-flex;align-items:center;min-height:32px;font-size:1rem}.review-card{margin:0 0 28px;padding:16px 0 24px;border-bottom:2px solid var(--color-wine);scroll-margin-top:16px}.review-card>h2{font-size:1.125rem;margin-bottom:6px}.review-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-top:16px}.review-pane{min-width:0;padding:12px;background:var(--color-sand);border:1px solid var(--color-wine)}.review-pane h3{font-size:.75rem;line-height:1.2;margin:0 0 10px}.review-pane p{font-size:1rem;margin:8px 0}.review-pane img:not(.sdp-motif image){display:block;max-width:100%;height:auto;margin:0 auto 10px;image-rendering:pixelated}.native-stage{max-width:100%;overflow:auto;padding:4px 4px 14px;background:var(--color-vanilla)}.native-stage>.sdp-dashboard{display:block;margin:0 auto;max-width:100%}.native-stage .live-candidate{margin-bottom:0}.live-candidate>svg.sdp-frame{display:none}.candidate-skin{position:absolute!important;top:-2px;left:-2px;width:calc(100% + 4px);height:calc(100% + 4px);box-sizing:border-box;pointer-events:none;border-style:solid;border-color:transparent;border-image-repeat:stretch;z-index:0}.live-candidate>:not(.sdp-frame){z-index:1}.live-candidate.sdp-card-report::before,.live-candidate.sdp-card-report::after{display:none}.live-candidate.sdp-card-report>.sdp-report-action>.pixel-frame{display:none}.live-candidate.sdp-card-report>.sdp-priority-label{background:none;border-color:transparent}/* Generated bookmarks and dividers need wider content insets than the SVG frames. */
.native-stage .live-candidate.sdp-report-priority .sdp-report-row{padding-inline:16px}
.native-stage .live-candidate.sdp-card-report:not(.sdp-report-priority) .sdp-report-row{padding-inline:52px 38px}
.native-stage .live-candidate.sdp-card-event .sdp-event-body{gap:16px}
.native-stage .live-candidate>.sdp-priority-label{top:0;right:20px}
.review-pane label{display:block;font-size:1rem;margin-bottom:6px}.review-pane select{width:100%;min-height:44px;margin-bottom:12px;color:var(--color-wine);background:var(--color-vanilla);border:1px solid var(--color-wine);padding:4px}.review-note{padding:6px 8px;background:var(--color-vanilla);border-left:3px solid var(--color-cherry)}.review-footer{font-size:1rem}.review :is(p,h1,h2,h3,a,label){overflow-wrap:anywhere}@media(max-width:1500px){.review-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.review-grid{grid-template-columns:minmax(0,1fr)}.review{padding:16px 12px}}
</style></head><body><main class="review"><header><h1>SDP cards — all 10</h1><p>Ten completed Higgsfield candidates, quoted at 15 credits total. This review uses frozen visual-fixture content and does not read or save demo records.</p><p>Compare the source picture, current implementation, cleaned source-border study and Higgsfield backing. The last column places a selectable backing under live HTML text, illustrations and links. Production dashboard frames retain their current treatment until reviewed.</p><p>Preparation removes background halos and text-removal blotches, restores blank surfaces/dividers, and maps colours to the approved five-token palette. Raw generations remain available. Proportion differences are shown for review, rather than silently stretching image thumbnails.</p><a href="/sdp-workspace.html#sdp">Open SDP dashboard</a><nav class="card-index" aria-label="Card index"></nav></header><div id="cards"></div><footer class="review-footer">Review set only · Original artwork and generation records retained in this folder · Live labels use Bungee and Yanone Kaffeesatz</footer></main>'''
script='''<script type="application/json" id="card-data">'''+payload+'''</script><script>
const cards=JSON.parse(document.getElementById('card-data').textContent);
const list=document.getElementById('cards'),index=document.querySelector('.card-index');
for(const [position,item] of cards.entries()){
 const article=document.createElement('article');article.className='review-card';article.dataset.cardId=item.id;article.id='card-'+item.id;
 const count=String(position+1).padStart(2,'0');const link=document.createElement('a');link.href='#'+article.id;link.textContent=count+' '+item.name;index.append(link);
 article.innerHTML=`<h2>${count} / ${item.name}</h2><p>Reference crop: ${item.native_size.join(' × ')}px · Generated silhouette proportion difference: ${item.qa.aspect_difference_percent}%</p><div class="review-grid"><section class="review-pane"><h3>Original picture</h3><img class="reference-image" src="references/${item.id}.png" alt="Original ${item.name}" style="width:${item.native_size[0]}px"><a href="references/${item.id}.png">Inspect original crop</a></section><section class="review-pane"><h3>Current implementation</h3><img class="current-image" src="current/${item.id}.png" alt="Current ${item.name}" style="width:${item.current_size.width}px"><p>Unmodified card capture with fixture content.</p></section><section class="review-pane"><h3>Blank backing candidates</h3><p>Cleaned source-border study</p><img class="source-image" src="source-studies/${item.id}.png" alt="Source-border study for ${item.name}" style="width:${item.native_size[0]}px"><p>Prepared Higgsfield candidate</p><img class="generated-image" src="prepared/${item.id}.png" alt="Higgsfield backing for ${item.name}" style="width:${item.native_size[0]}px"><a href="generated/${item.id}.png">Inspect unmodified generation</a><p class="review-note">${item.qa.review_note}. These are candidates, not accepted pixel matches.</p></section><section class="review-pane"><h3>Live-content preview</h3><label for="choice-${item.id}">Backing for ${item.name}</label><select id="choice-${item.id}"><option value="prepared">Higgsfield candidate</option><option value="source-studies">Source-border study</option></select><div class="native-stage"><div class="sdp-dashboard"></div></div><p>Nine-slice decoration; real text and links. Preview fits this panel.</p></section></div>`;
 const stage=article.querySelector('.native-stage>.sdp-dashboard');stage.style.width=item.current_size.width+'px';stage.innerHTML=item.current_html;const card=stage.firstElementChild;card.classList.add('live-candidate');
 for(const title of card.querySelectorAll('h1')){const h=document.createElement('h2');for(const a of title.attributes)h.setAttribute(a.name,a.value);h.innerHTML=title.innerHTML;title.replaceWith(h);}
 const ids=new Map();for(const el of card.querySelectorAll('[id]')){ids.set(el.id,el.id+'-'+item.id);el.id=ids.get(el.id);}
 for(const el of card.querySelectorAll('[aria-labelledby],[aria-describedby]'))for(const attr of ['aria-labelledby','aria-describedby'])if(el.hasAttribute(attr))el.setAttribute(attr,el.getAttribute(attr).split(' ').map(id=>ids.get(id)||id).join(' '));
 for(const a of card.querySelectorAll('a[href^="#"]'))a.setAttribute('href','/sdp-workspace.html'+a.getAttribute('href'));
 const skin=document.createElement('div');skin.className='sdp-frame candidate-skin';skin.setAttribute('aria-hidden','true');
 const cuts=item.kind==='report'?[32,42,28,42]:item.kind==='welcome'?[27,16,16,16]:item.kind==='event'?[16,14,14,14]:item.kind==='metric'?[10,10,12,10]:[18,18,18,18];
 skin.style.borderWidth=cuts.map(x=>x+'px').join(' ');skin.style.borderImageSlice=cuts.join(' ')+' fill';skin.style.borderImageSource=`url("prepared/${item.id}.png")`;card.prepend(skin);
 article.querySelector('select').addEventListener('change',event=>{skin.style.borderImageSource=`url("${event.target.value}/${item.id}.png")`;});list.append(article);
}
</script></body></html>'''
(root/'review.html').write_text(head+script,encoding='utf-8');print('Ten-card review page built with source, current, two backing candidates and live HTML previews.')
